"""Document newly reported release gates without changing runtime code or workflows."""
import base64
import hashlib
import json
import lzma
from pathlib import Path

PAYLOAD = """"""
raw = lzma.decompress(base64.b64decode(PAYLOAD, validate=True))
assert hashlib.sha256(raw).hexdigest() == "9dd67c1e7abed54a88d0260b55270f0b176b321c4c1f954ccbc7ac816f8847b7"
entries = json.loads(raw)
assert len(entries) == 4
for entry in entries:
    path = Path(entry['path'])
    assert not path.is_absolute() and '..' not in path.parts
    assert path.suffix == '.md' and str(path).startswith(('docs/guide/', '.agents/skills/'))
    old = path.read_bytes()
    assert hashlib.sha256(old).hexdigest() == entry['base'], path
    lines = old.decode().splitlines(keepends=True)
    for start, end, text in reversed(entry['edits']):
        lines[start:end] = [text]
    new = ''.join(lines).encode()
    assert hashlib.sha256(new).hexdigest() == entry['result'], path
    path.write_bytes(new)
